import React, { useState, useMemo, useEffect } from &#39;react&#39;;
import { 
  Settings, GitFork, ListOrdered, Shapes, 
  Globe, RefreshCcw, Users, Calculator, 
  MapPin, Sparkles, BookHeart, Dices
} from &#39;lucide-react&#39;;

// --- Global Dice Scenarios Data ---
const SCENARIOS = [
  {
    id: &#39;handful&#39;,
    title: &quot;The Yahtzee Grandmaster&quot;,
    location: &quot;Ohio, USA&quot;,
    theme: { color: &#39;stroke-amber-500&#39;, bg: &#39;bg-amber-50&#39;, border: &#39;border-amber-200&#39;, text: &#39;text-amber-700&#39; },
    items: [&#39;⚀&#39;, &#39;⚁&#39;, &#39;⚂&#39;, &#39;⚃&#39;, &#39;⚄&#39;, &#39;⚅&#39;],
    defaultTotal: 3,
    defaultMode: &#39;repetition&#39;,
    defaultLogic: &#39;combination&#39;,
    insight: &quot;When I roll a handful of bones, I&#39;m looking for sets. A &#39;Full House&#39; is a Combination with Repetition. If my dice land showing ⚂-⚄-⚂, it&#39;s the exact same hand as ⚄-⚂-⚂. The dice don&#39;t have a memory of who hit the felt first.&quot;,
    intuition: &quot;Order is an illusion here. The tree prunes away scrambled duplicates, forcing us to only look at the unique &#39;mixtures&#39; of numbers.&quot;
  },
  {
    id: &#39;sequence&#39;,
    title: &quot;The Sic Bo Actuary&quot;,
    location: &quot;Macau, China&quot;,
    theme: { color: &#39;stroke-purple-500&#39;, bg: &#39;bg-purple-50&#39;, border: &#39;border-purple-200&#39;, text: &#39;text-purple-700&#39; },
    items: [&#39;⚀&#39;, &#39;⚁&#39;, &#39;⚂&#39;, &#39;⚃&#39;, &#39;⚄&#39;, &#39;⚅&#39;],
    defaultTotal: 3,
    defaultMode: &#39;repetition&#39;,
    defaultLogic: &#39;permutation&#39;,
    insight: &quot;To calculate the true house edge, I cannot look at the handful; I must look at the sequence. Rolling a 7 by hitting a ⚂ then a ⚃ is a distinct timeline from hitting a ⚃ then a ⚂. Both must be mapped to find the true probability.&quot;,
    intuition: &quot;The Master Tree in its purest form. Infinite reuse, and every distinct timeline matters. No branches are pruned.&quot;
  },
  {
    id: &#39;locksmith&#39;,
    title: &quot;The Codebreaker&quot;,
    location: &quot;Bletchley Park, UK&quot;,
    theme: { color: &#39;stroke-blue-500&#39;, bg: &#39;bg-blue-50&#39;, border: &#39;border-blue-200&#39;, text: &#39;text-blue-700&#39; },
    items: [&#39;⚀&#39;, &#39;⚁&#39;, &#39;⚂&#39;, &#39;⚃&#39;, &#39;⚄&#39;, &#39;⚅&#39;],
    defaultTotal: 4,
    defaultMode: &#39;selection&#39;,
    defaultLogic: &#39;permutation&#39;,
    insight: &quot;We are using dice faces to set a rotary combination lock. To maximize security, the rules state no number can be repeated. Entering ⚁-⚃ is the password; entering ⚃-⚁ triggers the alarm.&quot;,
    intuition: &quot;Finite resources where sequence is absolute. The tree deletes any path that tries to reuse a number, leaving only unique sequences.&quot;
  },
  {
    id: &#39;drafting&#39;,
    title: &quot;The Board Game Designer&quot;,
    location: &quot;Essen, Germany&quot;,
    theme: { color: &#39;stroke-emerald-500&#39;, bg: &#39;bg-emerald-50&#39;, border: &#39;border-emerald-200&#39;, text: &#39;text-emerald-700&#39; },
    items: [&#39;⚀&#39;, &#39;⚁&#39;, &#39;⚂&#39;, &#39;⚃&#39;, &#39;⚄&#39;, &#39;⚅&#39;],
    defaultTotal: 4,
    defaultMode: &#39;selection&#39;,
    defaultLogic: &#39;combination&#39;,
    insight: &quot;Players draft action dice from a central pool to build their turn. You can&#39;t draft the same action twice, and you resolve them all simultaneously at the end. It doesn&#39;t matter what order you pulled them from the board.&quot;,
    intuition: &quot;The strictest reduction. No duplicates allowed, and the sequence of drafting is ignored. The tree is pruned to its absolute minimum.&quot;
  }
];

// --- Recursive Tree Component with Ghosting Logic ---
const TreeBranch = ({ 
  node, x, y, spacing, depth, maxDepth, 
  activeHoverPath, currentPath = [], currentIndices = [],
  mode, logic, themeColor
}) =&gt; {
  if (!node || !node.children || node.children.length === 0 || depth &gt;= maxDepth) return null;
  const totalWidth = (node.children.length - 1) * spacing;

  return (
    &lt;g&gt;
      {node.children.map((child, i) =&gt; {
        const childX = x - totalWidth / 2 + i * spacing;
        const childY = y + 55;

        const thisPath = [...currentPath, child.name];
        const thisIndices = [...currentIndices, child.index];

        const isUnique = new Set(thisIndices).size === thisIndices.length;
        let isSorted = true;
        for (let j = 1; j &lt; thisIndices.length; j++) {
          if (mode === &#39;selection&#39; &amp;&amp; thisIndices[j] &lt;= thisIndices[j-1]) isSorted = false;
          if (mode === &#39;repetition&#39; &amp;&amp; thisIndices[j] &lt; thisIndices[j-1]) isSorted = false;
        }

        let isValid = true;
        if (mode === &#39;selection&#39; &amp;&amp; !isUnique) isValid = false;
        if (logic === &#39;combination&#39; &amp;&amp; !isSorted) isValid = false;

        const isPathHovered = activeHoverPath &amp;&amp; activeHoverPath[depth] === child.name &amp;&amp; activeHoverPath.join(&#39;&#39;) === thisPath.slice(0, activeHoverPath.length).join(&#39;&#39;);

        let strokeColor, strokeWidth, circleFill, textColor;

        if (activeHoverPath) {
          if (isPathHovered) {
            strokeColor = themeColor;
            strokeWidth = &#39;stroke-[3px]&#39;;
            circleFill = themeColor.replace(&#39;stroke-&#39;, &#39;fill-&#39;);
            textColor = &#39;fill-white&#39;;
          } else {
            strokeColor = &#39;stroke-slate-200 opacity-20&#39;;
            strokeWidth = &#39;stroke-[1.5px]&#39;;
            circleFill = &#39;fill-white opacity-20&#39;;
            textColor = &#39;fill-slate-400 opacity-20&#39;;
          }
        } else {
          if (isValid) {
            strokeColor = themeColor;
            strokeWidth = &#39;stroke-[2px]&#39;;
            circleFill = &#39;fill-white&#39;;
            textColor = &#39;fill-slate-700&#39;;
          } else {
            strokeColor = &#39;stroke-slate-200 opacity-30&#39;;
            strokeWidth = &#39;stroke-[1.5px] stroke-dasharray-[2,2]&#39;;
            circleFill = &#39;fill-slate-50 opacity-50&#39;;
            textColor = &#39;fill-slate-300 opacity-50&#39;;
          }
        }

        return (
          &lt;React.Fragment key={`branch-${depth}-${i}-${child.name}`}&gt;
            &lt;line 
              x1={x} y1={y + 12} x2={childX} y2={childY - 12} 
              className={`${strokeWidth} ${strokeColor} transition-all duration-500`}
            /&gt;
            &lt;g transform={`translate(${childX}, ${childY})`}&gt;
              &lt;circle r=&quot;14&quot; className={`${circleFill} ${strokeWidth} ${strokeColor} transition-all duration-500`} /&gt;
              &lt;text 
                textAnchor=&quot;middle&quot; dy=&quot;5&quot; 
                className={`text-sm font-bold pointer-events-none select-none ${textColor} transition-all duration-500`}
              &gt;
                {child.name}
              &lt;/text&gt;
              &lt;TreeBranch 
                node={child} x={0} y={0} spacing={spacing * 0.45} depth={depth + 1} 
                maxDepth={maxDepth} activeHoverPath={isPathHovered ? activeHoverPath : null}
                currentPath={thisPath} currentIndices={thisIndices} mode={mode} logic={logic} themeColor={themeColor}
              /&gt;
            &lt;/g&gt;
          &lt;/React.Fragment&gt;
        );
      })}
    &lt;/g&gt;
  );
};

const App = () =&gt; {
  const [activeScenarioId, setActiveScenarioId] = useState(SCENARIOS[0].id);
  const scenario = SCENARIOS.find(s =&gt; s.id === activeScenarioId);

  const [mode, setMode] = useState(scenario.defaultMode); 
  const [logic, setLogic] = useState(scenario.defaultLogic); 
  const [totalItems, setTotalItems] = useState(scenario.defaultTotal);
  const [groupSize, setGroupSize] = useState(2);
  const [activePath, setActivePath] = useState(null);

  useEffect(() =&gt; {
    setMode(scenario.defaultMode);
    setLogic(scenario.defaultLogic);
    setTotalItems(scenario.defaultTotal);
    setActivePath(null);
  }, [scenario.id]);

  const items = useMemo(() =&gt; scenario.items.slice(0, totalItems), [scenario, totalItems]);
  const fact = (num) =&gt; (num &lt;= 1 ? 1 : num * fact(num - 1));

  const mathDetails = useMemo(() =&gt; {
    const n = totalItems;
    const r = groupSize;
    if (mode === &#39;selection&#39; &amp;&amp; logic === &#39;permutation&#39;) {
      return { notation: `P(${n},${r})`, formula: `n! / (n-r)!`, count: fact(n) / fact(n - r) };
    } else if (mode === &#39;selection&#39; &amp;&amp; logic === &#39;combination&#39;) {
      return { notation: `C(${n},${r})`, formula: `n! / [r!(n-r)!]`, count: fact(n) / (fact(r) * fact(n - r)) };
    } else if (mode === &#39;repetition&#39; &amp;&amp; logic === &#39;permutation&#39;) {
      return { notation: `n^r`, formula: `n^r`, count: Math.pow(n, r) };
    } else {
      return { notation: `C(${n}+${r}-1, ${r})`, formula: `(n+r-1)! / [r!(n-1)!]`, count: fact(n + r - 1) / (fact(r) * fact(n - 1)) };
    }
  }, [totalItems, groupSize, mode, logic]);

  // Master Tree Generation
  const masterTreeData = useMemo(() =&gt; {
    const root = { name: &quot;Start&quot;, children: [], index: -1 };
    const build = (node, depth) =&gt; {
      if (depth === groupSize) return;
      items.forEach((item, idx) =&gt; {
        const child = { name: item, index: idx, children: [] };
        node.children.push(child);
        // Limit depth in rendering to prevent browser lockup for 6^3
        if (depth &lt; (totalItems &gt; 4 ? 1 : 2)) build(child, depth + 1); 
      });
    };
    build(root, 0);
    return root;
  }, [items, groupSize, totalItems]);

  // Generate Valid Paths
  const validPaths = useMemo(() =&gt; {
    let res = [];
    const bt = (currPath, currIndices) =&gt; {
      if (currPath.length === groupSize) {
        const isUnique = new Set(currIndices).size === currIndices.length;
        let isSorted = true;
        for (let j = 1; j &lt; currIndices.length; j++) {
          if (mode === &#39;selection&#39; &amp;&amp; currIndices[j] &lt;= currIndices[j-1]) isSorted = false;
          if (mode === &#39;repetition&#39; &amp;&amp; currIndices[j] &lt; currIndices[j-1]) isSorted = false;
        }

        let isValid = true;
        if (mode === &#39;selection&#39; &amp;&amp; !isUnique) isValid = false;
        if (logic === &#39;combination&#39; &amp;&amp; !isSorted) isValid = false;

        if (isValid) res.push([...currPath]);
        return;
      }

      items.forEach((item, idx) =&gt; {
        currPath.push(item);
        currIndices.push(idx);
        bt(currPath, currIndices);
        currPath.pop();
        currIndices.pop();
      });
    };
    bt([], []);
    return res;
  }, [items, groupSize, mode, logic]);

  return (
    &lt;div className=&quot;min-h-screen bg-slate-50 p-4 md:p-8 font-sans text-slate-900 selection:bg-slate-200&quot;&gt;

      &lt;header className=&quot;max-w-7xl mx-auto mb-8&quot;&gt;
        &lt;div className=&quot;flex flex-col md:flex-row justify-between items-end gap-6 border-b border-slate-200 pb-6&quot;&gt;
          &lt;div className=&quot;max-w-2xl&quot;&gt;
            &lt;h1 className=&quot;text-4xl md:text-5xl font-black text-slate-800 tracking-tight mb-3 flex items-center gap-3&quot;&gt;
              &lt;Dices className=&quot;text-slate-400&quot; size={40} /&gt;
              The Geometry of Chance
            &lt;/h1&gt;
            &lt;p className=&quot;text-slate-500 text-lg leading-relaxed&quot;&gt;
              Explore the four quadrants of probability. See how the Master Tree is pruned based on whether you are throwing a handful of dice, or rolling them in an exact sequence.
            &lt;/p&gt;
          &lt;/div&gt;

          &lt;div className=&quot;flex flex-col items-end gap-2 w-full md:w-auto&quot;&gt;
            &lt;div className=&quot;text-[10px] font-bold uppercase tracking-widest text-slate-400&quot;&gt;Select Dice Context&lt;/div&gt;
            &lt;div className=&quot;flex gap-2 overflow-x-auto w-full pb-2 md:pb-0 custom-scrollbar&quot;&gt;
              {SCENARIOS.map(s =&gt; (
                &lt;button
                  key={s.id}
                  onClick={() =&gt; setActiveScenarioId(s.id)}
                  className={`px-4 py-2 rounded-xl text-xs font-bold whitespace-nowrap transition-all border ${activeScenarioId === s.id ? `${s.theme.bg} ${s.theme.text} border-${s.theme.color.split(&#39;-&#39;)[1]}-300 shadow-sm` : &#39;bg-white text-slate-500 border-slate-200 hover:bg-slate-50&#39;}`}
                &gt;
                  {s.title}
                &lt;/button&gt;
              ))}
            &lt;/div&gt;
          &lt;/div&gt;
        &lt;/div&gt;
      &lt;/header&gt;

      &lt;main className=&quot;max-w-7xl mx-auto grid grid-cols-1 xl:grid-cols-12 gap-6&quot;&gt;

        {/* Left Column: Context &amp; Controls */}
        &lt;section className=&quot;xl:col-span-4 flex flex-col gap-6&quot;&gt;

          {/* Context Card */}
          &lt;div className={`p-6 rounded-3xl border transition-all duration-500 ${scenario.theme.bg} ${scenario.theme.border}`}&gt;
            &lt;div className=&quot;flex items-start justify-between mb-4&quot;&gt;
              &lt;div&gt;
                &lt;h2 className={`text-xl font-black ${scenario.theme.text}`}&gt;{scenario.title}&lt;/h2&gt;
                &lt;div className={`flex items-center gap-1 text-xs font-bold mt-1 opacity-70 ${scenario.theme.text}`}&gt;
                  &lt;MapPin size={12} /&gt; {scenario.location}
                &lt;/div&gt;
              &lt;/div&gt;
              &lt;div className=&quot;flex gap-0.5 bg-white/50 px-2 py-1.5 rounded-lg border border-white&quot;&gt;
                {scenario.items.map((it, idx) =&gt; (
                  &lt;span key={idx} className=&quot;text-xl&quot;&gt;{it}&lt;/span&gt;
                ))}
              &lt;/div&gt;
            &lt;/div&gt;
            &lt;p className={`text-sm leading-relaxed italic opacity-90 ${scenario.theme.text}`}&gt;
              &quot;{scenario.insight}&quot;
            &lt;/p&gt;
          &lt;/div&gt;

          {/* Controls */}
          &lt;div className=&quot;bg-white p-6 rounded-3xl shadow-sm border border-slate-200&quot;&gt;
            &lt;div className=&quot;flex items-center gap-2 mb-6 text-slate-800 font-bold uppercase tracking-widest text-xs&quot;&gt;
              &lt;Settings size={16} /&gt;
              &lt;span&gt;Table Rules&lt;/span&gt;
            &lt;/div&gt;

            &lt;div className=&quot;space-y-6&quot;&gt;
              &lt;div className=&quot;grid grid-cols-2 gap-3&quot;&gt;
                &lt;div className=&quot;space-y-2&quot;&gt;
                  &lt;label className=&quot;block text-[9px] font-bold text-slate-400 uppercase tracking-widest&quot;&gt;Duplicates&lt;/label&gt;
                  &lt;button onClick={() =&gt; setMode(&#39;repetition&#39;)} className={`w-full py-2 px-2 rounded-xl border text-xs font-bold transition-all flex items-center justify-center gap-2 ${mode === &#39;repetition&#39; ? &#39;bg-slate-800 text-white border-slate-800&#39; : &#39;bg-slate-50 text-slate-500 border-slate-100 hover:border-slate-300&#39;}`}&gt;
                    &lt;RefreshCcw size={14} /&gt; Allowed
                  &lt;/button&gt;
                  &lt;button onClick={() =&gt; setMode(&#39;selection&#39;)} className={`w-full py-2 px-2 rounded-xl border text-xs font-bold transition-all flex items-center justify-center gap-2 ${mode === &#39;selection&#39; ? &#39;bg-slate-800 text-white border-slate-800&#39; : &#39;bg-slate-50 text-slate-500 border-slate-100 hover:border-slate-300&#39;}`}&gt;
                    &lt;Users size={14} /&gt; Prevented
                  &lt;/button&gt;
                &lt;/div&gt;
                &lt;div className=&quot;space-y-2&quot;&gt;
                  &lt;label className=&quot;block text-[9px] font-bold text-slate-400 uppercase tracking-widest&quot;&gt;Sequence&lt;/label&gt;
                  &lt;button onClick={() =&gt; setLogic(&#39;permutation&#39;)} className={`w-full py-2 px-2 rounded-xl border text-xs font-bold transition-all flex items-center justify-center gap-2 ${logic === &#39;permutation&#39; ? &#39;bg-slate-800 text-white border-slate-800&#39; : &#39;bg-slate-50 text-slate-500 border-slate-100 hover:border-slate-300&#39;}`}&gt;
                    &lt;ListOrdered size={14} /&gt; Tracked
                  &lt;/button&gt;
                  &lt;button onClick={() =&gt; setLogic(&#39;combination&#39;)} className={`w-full py-2 px-2 rounded-xl border text-xs font-bold transition-all flex items-center justify-center gap-2 ${logic === &#39;combination&#39; ? &#39;bg-slate-800 text-white border-slate-800&#39; : &#39;bg-slate-50 text-slate-500 border-slate-100 hover:border-slate-300&#39;}`}&gt;
                    &lt;Shapes size={14} /&gt; Ignored
                  &lt;/button&gt;
                &lt;/div&gt;
              &lt;/div&gt;

              &lt;div className=&quot;pt-4 border-t border-slate-100 space-y-4&quot;&gt;
                &lt;div&gt;
                  &lt;label className=&quot;flex justify-between text-[10px] font-bold text-slate-500 uppercase mb-2&quot;&gt;
                    &lt;span&gt;Faces on Die ($n$)&lt;/span&gt;
                    &lt;span className=&quot;text-slate-800&quot;&gt;{totalItems}&lt;/span&gt;
                  &lt;/label&gt;
                  &lt;input type=&quot;range&quot; min=&quot;2&quot; max=&quot;6&quot; value={totalItems} onChange={(e) =&gt; { setTotalItems(parseInt(e.target.value)); if (groupSize &gt; parseInt(e.target.value) &amp;&amp; mode === &#39;selection&#39;) setGroupSize(parseInt(e.target.value)); }} className=&quot;w-full h-1 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-slate-800&quot; /&gt;
                &lt;/div&gt;
                &lt;div&gt;
                  &lt;label className=&quot;flex justify-between text-[10px] font-bold text-slate-500 uppercase mb-2&quot;&gt;
                    &lt;span&gt;Dice Thrown ($r$)&lt;/span&gt;
                    &lt;span className=&quot;text-slate-800&quot;&gt;{groupSize}&lt;/span&gt;
                  &lt;/label&gt;
                  &lt;input type=&quot;range&quot; min=&quot;1&quot; max={mode === &#39;selection&#39; ? totalItems : 3} value={groupSize} onChange={(e) =&gt; setGroupSize(parseInt(e.target.value))} className=&quot;w-full h-1 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-slate-800&quot; /&gt;
                &lt;/div&gt;
              &lt;/div&gt;
            &lt;/div&gt;
          &lt;/div&gt;

          {/* Math Lens */}
          &lt;div className=&quot;bg-slate-900 p-6 rounded-3xl shadow-xl relative overflow-hidden flex-1 flex flex-col justify-center&quot;&gt;
            &lt;div className=&quot;absolute top-0 right-0 p-4 opacity-5 text-white&quot;&gt;
              &lt;Calculator size={100} /&gt;
            &lt;/div&gt;
            &lt;h3 className=&quot;text-[10px] font-bold uppercase tracking-widest mb-2 text-slate-400&quot;&gt;Formal Translation&lt;/h3&gt;
            &lt;div className=&quot;flex items-end gap-3 mb-4&quot;&gt;
              &lt;div className=&quot;text-5xl font-mono font-black text-white&quot;&gt;{mathDetails.count}&lt;/div&gt;
              &lt;div className=&quot;text-sm font-mono mb-1 text-slate-400&quot;&gt;Possible Outcomes&lt;/div&gt;
            &lt;/div&gt;
            &lt;div className=&quot;bg-white/10 p-3 rounded-xl border border-white/10&quot;&gt;
              &lt;div className=&quot;text-lg font-mono text-emerald-400&quot;&gt;{mathDetails.notation} = {mathDetails.formula}&lt;/div&gt;
            &lt;/div&gt;
          &lt;/div&gt;

        &lt;/section&gt;

        {/* Right Column: Visualizer &amp; Results */}
        &lt;section className=&quot;xl:col-span-8 flex flex-col gap-6&quot;&gt;

          &lt;div className=&quot;bg-white p-6 rounded-3xl shadow-sm border border-slate-200 flex flex-col md:flex-row gap-6 h-[550px]&quot;&gt;

             {/* The Tree Map */}
             &lt;div className=&quot;flex-1 flex flex-col relative h-full&quot;&gt;
                &lt;div className=&quot;flex items-center justify-between mb-2 relative z-10&quot;&gt;
                  &lt;div className=&quot;flex items-center gap-2 font-bold uppercase tracking-widest text-xs text-slate-800&quot;&gt;
                    &lt;GitFork size={18} /&gt;
                    &lt;span&gt;Probability Branches&lt;/span&gt;
                  &lt;/div&gt;
                  {mode === scenario.defaultMode &amp;&amp; logic === scenario.defaultLogic &amp;&amp; (
                    &lt;span className={`text-[9px] font-bold uppercase px-2 py-1 rounded-full ${scenario.theme.bg} ${scenario.theme.text} border ${scenario.theme.border}`}&gt;
                      Context Match
                    &lt;/span&gt;
                  )}
                &lt;/div&gt;

                &lt;div className=&quot;flex-1 bg-slate-50/50 rounded-2xl border border-slate-100 overflow-hidden relative z-10&quot;&gt;
                  &lt;svg width=&quot;100%&quot; height=&quot;100%&quot; viewBox=&quot;0 0 600 450&quot; preserveAspectRatio=&quot;xMidYMin meet&quot;&gt;
                    &lt;g transform=&quot;translate(300, 30)&quot;&gt;
                      &lt;circle r=&quot;14&quot; className=&quot;fill-slate-800&quot; /&gt;
                      &lt;text textAnchor=&quot;middle&quot; dy=&quot;3&quot; className=&quot;fill-white text-[8px] font-bold&quot;&gt;ROLL&lt;/text&gt;
                      &lt;TreeBranch 
                        node={masterTreeData} 
                        x={0} y={0} 
                        spacing={totalItems &gt; 4 ? totalItems * 25 : totalItems * 45} 
                        depth={0} 
                        themeColor={scenario.theme.color}
                        maxDepth={totalItems &gt; 4 &amp;&amp; groupSize === 3 ? 2 : groupSize} // Visual cap for huge trees
                        activeHoverPath={activePath}
                        mode={mode}
                        logic={logic}
                      /&gt;
                    &lt;/g&gt;
                  &lt;/svg&gt;
                  {totalItems &gt; 4 &amp;&amp; groupSize === 3 &amp;&amp; (
                    &lt;div className=&quot;absolute bottom-4 left-0 w-full flex justify-center&quot;&gt;
                      &lt;div className=&quot;bg-white/90 backdrop-blur px-3 py-1.5 rounded-full border border-slate-200 text-[9px] font-bold text-slate-500 shadow-sm&quot;&gt;
                        Tree graphic truncated to depth 2 due to massive complexity. List displays all {mathDetails.count} paths.
                      &lt;/div&gt;
                    &lt;/div&gt;
                  )}
                &lt;/div&gt;
             &lt;/div&gt;

             {/* Dynamic Results */}
             &lt;div className=&quot;w-full md:w-64 flex flex-col h-full&quot;&gt;
                &lt;div className=&quot;flex-1 bg-slate-50 rounded-2xl border border-slate-100 p-4 flex flex-col overflow-hidden h-full&quot;&gt;
                  &lt;div className=&quot;flex flex-col gap-1 mb-3&quot;&gt;
                    &lt;h3 className=&quot;text-[10px] font-bold text-slate-500 uppercase tracking-widest&quot;&gt;
                      Valid Dice Results
                    &lt;/h3&gt;
